    status text DEFAULT 'PENDING'::text NOT NULL,
    matched_ref text,
    matched_at timestamp with time zone,
    ledger_entry_id uuid,
    decided_by uuid,
    decided_at timestamp with time zone,
    note text,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    received_amount integer,
    credited integer,
    target_pocket text DEFAULT 'SALDO'::text NOT NULL,
    alloc_spp integer DEFAULT 0 NOT NULL,
    alloc_laundry integer DEFAULT 0 NOT NULL,
    CONSTRAINT topup_requests_alloc_laundry_check CHECK ((alloc_laundry >= 0)),
    CONSTRAINT topup_requests_alloc_spp_check CHECK ((alloc_spp >= 0)),
    CONSTRAINT topup_requests_amount_check CHECK ((amount > 0)),
    CONSTRAINT topup_requests_check CHECK ((total = ((amount + unique_code) + fee))),
    CONSTRAINT topup_requests_credited_check CHECK ((credited > 0)),
    CONSTRAINT topup_requests_fee_check CHECK ((fee >= 0)),
    CONSTRAINT topup_requests_received_amount_check CHECK ((received_amount > 0)),
    CONSTRAINT topup_requests_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'MATCHED'::text, 'CREDITED'::text, 'REJECTED'::text, 'EXPIRED'::text, 'CANCELLED'::text]))),
    CONSTRAINT topup_requests_target_pocket_check CHECK ((target_pocket = ANY (ARRAY['SALDO'::text, 'JAJAN'::text, 'LAUNDRY'::text, 'SPP'::text]))),
    CONSTRAINT topup_requests_unique_code_check CHECK (((unique_code >= 1) AND (unique_code <= 999)))
);


--
-- Name: fee_items; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.fee_items AS
 SELECT t.id,
    t.santri_id,
    t.decided_at AS at,
    COALESCE(t.credited, (t.amount + t.unique_code)) AS credited,
    t.fee,
    t.total,
    'TRANSFER'::text AS kind
   FROM public.topup_requests t
  WHERE ((t.status = 'CREDITED'::text) AND (t.decided_at IS NOT NULL))
UNION ALL
 SELECT c.id,
    c.santri_id,
    c.created_at AS at,
    c.amount AS credited,
    c.fee,
    (c.amount + c.fee) AS total,
    'TUNAI'::text AS kind
   FROM public.cash_topups c;


